\end{definition}

n25577.content:
\begin{proposition}[The group algebra functor is fully faithful]
  \label{0-full-faithful-grp-alg}
  \uses{0-grp-alg}
  \lean{MonoidAlgebra.mapDomainBialgHomMulEquiv, AddMonoidAlgebra.mapDomainBialgHomAddEquiv, commGrpAlg.fullyFaithful, commGrpAlg.instFull, commGrpAlg.instFaithful}
  \leanok

  Let $R$ be a domain.
  The functor $G \rightsquigarrow R[G]$ from the category of groups to the category of Hopf algebras over $R$ is fully faithful.
\end{proposition}

n25578.content:
\begin{proof}
  \uses{0-grp-like-grp-alg, 0-grp-like-map}
  \leanok

  The functor is clearly faithful.
  Now for the full part, if $f : R[G] \to R[H]$ is a Hopf algebra hom, then we get a series of maps
  \[
    G \simeq \text{ group-like elements of } R[G] \to \text{ group-like elements of } R[H] \simeq H
  \]
  and each map separately is clearly multiplicative.
\end{proof}

n25579.content:
\begin{definition}[Convex cone generated by a set]
  \label{1-2-1-cone-hull}
  % \uses{}
  \lean{Submodule.span}
  \leanok

  For a set $S \subseteq N$, the {\bf cone generated by $S$}, aka {\bf cone hull of $S$}, is
  $$\Cone(S) := \left\{\sum_{u \in S} \lambda_u u | \lambda_u \ge 0\right\}$$
\end{definition}

n25580.content:
\begin{definition}[Convex polyhedral cone]
  \label{1-2-1-polyhedral-cone}
  \uses{1-2-1-cone-hull}
  % \lean{PointedCone.IsPolyhedral} In Polyhedral for now
  \leanok

  A {\bf polyhedral cone} is a set that can be written as $\Cone(S)$ for some finite set $S$.
\end{definition}

n25581.content:
\begin{definition}[Convex hull]
  \label{1-2-2-convex-hull}
  % \uses{}
  \lean{convexHull}
  \leanok

  For a set $S \subseteq N$, the {\bf convex hull of $S$} is
  $$\Conv(S) := \left\{\sum_{u \in S} \lambda_u | \lambda_u \ge 0, \sum_u \lambda_u = 1\right\}$$
\end{definition}

n25582.content:
\begin{definition}[Polytope]
  \label{1-2-2-polytope}
  \uses{1-2-2-convex-hull}
  % \lean{IsPolytope} In Polyhedral for now
  \leanok

  A {\bf polytope} is a set that can be written as $\Conv(S)$ for some finite set $S$.
\end{definition}

n25583.content:
\begin{definition}[Dual cone]
  \label{1-2-3-dual-cone}
  \uses{1-2-2-convex-hull}
  \lean{PointedCone.dual}
  \leanok

  Given a polyhedral cone $\sigma \subseteq N$, its {\bf dual cone} is defined by
  $$\sigma^\vee = \{m \in M | \forall u \in \sigma, \langle m, u\rangle \ge 0\}$$.
\end{definition}

n25584.content:
\begin{proposition}[Dual of a polyhedral cone]
  \label{1-2-4-dual-polyhedral-cone}
  \uses{1-2-1-polyhedral-cone, 1-2-3-dual-cone}
  % \lean{PointedCone.IsPolyhedral.dual} In Polyhedral for now
  \leanok

  If $\sigma$ is polyhedral, then its dual $\sigma^\vee$ is polyhedral too.
\end{proposition}

n25586.content:
\begin{proposition}[Dual cone of a sumset]
  \label{1-2-dual-cone-add}
  \uses{1-2-3-dual-cone}
  % \lean{}
  % \leanok

  If $\sigma_1, \sigma_2$ are two cones, then
  $$(\sigma_1 + \sigma_2)^\vee = \sigma_1^\vee \cap \sigma_2^\vee.$$
\end{proposition}

n25588.content:
\begin{proposition}[Double dual of a polyhedral cone]
  \label{1-2-4-double-dual-polyhedral-cone}
  \uses{1-2-1-polyhedral-cone, 1-2-3-dual-cone}
  % \lean{}
  % \leanok

  If $\sigma$ is polyhedral, then $\sigma^{\vee\vee} = \sigma$.
\end{proposition}

n25590.content:
\begin{definition}[Face of a cone]
  \label{1-2-5-face}
  % \uses{}
  \lean{IsExposed}
  \leanok

  If $\sigma$ is a cone, then a subset of $\sigma$ is a {\bf face} iff it is the intersection of $\sigma$ with some halfspace. We write this $\tau \preceq \sigma$. If furthermore $\tau \ne \sigma$, we call $\tau$ a proper face and write $\tau \prec \sigma$.
\end{definition}

n25591.content:
\begin{definition}[Edge of a cone]
  \label{1-2-5-edge}
  \uses{1-2-5-face}
  % \lean{}
  % \leanok

  A dimension 1 face of a cone is called an \emph{edge}.
\end{definition}

n25592.content:
\begin{definition}[Facet of a cone]
  \label{1-2-5-facet}
  \uses{1-2-5-face}
  % \lean{}
  % \leanok

  A codimension 1 face of a cone is called a \emph{facet}.
\end{definition}

n25593.content:
\begin{lemma}[Face of a polyhedral cone]
  \label{1-2-6-face-polyhedral-cone}
  \uses{1-2-1-polyhedral-cone, 1-2-5-face}
  % \lean{}
  % \leanok

  If $\sigma$ is a polyhedral cone, then every face of $\sigma$ is a polyhedral cone.
\end{lemma}

n25594.content:
\begin{lemma}[Intersection of faces]
  \label{1-2-6-inter-faces}
  \uses{1-2-1-polyhedral-cone, 1-2-5-face}
  % \lean{}
  % \leanok

  If $\sigma$ is a polyhedral cone, then the intersection of two faces of $\sigma$ is a face of $\sigma$.
\end{lemma}

n25596.content:
\begin{lemma}[Face of a face]
  \label{1-2-6-face-face}
  \uses{1-2-1-polyhedral-cone, 1-2-5-face}
  % \lean{}
  % \leanok

  A face of a face of a polyhedral cone $\sigma$ is again a face of $\sigma$.
\end{lemma}

n25598.content:
\begin{lemma}
  \label{1-2-7-face-mem-of-add}
  \uses{1-2-1-polyhedral-cone, 1-2-5-face}
  % \lean{}
  % \leanok

  Let $\tau$ be a face of a polyhedral cone $\sigma$. If $v, w \in \sigma$ and $v + w \in \tau$, then $v, w \in \tau$.
\end{lemma}

n25600.content:
\begin{proposition}[Dual cone of the intersection of halfspaces]
  \label{1-2-8-dual-cone-inter-halfspaces}
  \uses{1-2-1-cone-hull, 1-2-3-dual-cone}
  % \lean{}
  % \leanok

  If $\sigma = H_{m_1}^+ \cap \dots \cap H_{m_s}^+$, then
  $$\sigma^\vee = \Cone(m_1, \dots, m_s).$$
\end{proposition}

n25602.content:
\begin{proposition}[Facets of a full dimensional cone]
  \label{1-2-8-facet-full-dim-cone}
  \uses{1-2-1-cone-hull, 1-2-5-facet}
  % \lean{}
  % \leanok

  If $\sigma$ is a full dimensional cone, then facets of $\sigma$ are of the form $H_m \cap \sigma$.
\end{proposition}

n25604.content:
\begin{proposition}[Intersection of facets containing a face]
  \label{1-2-8-inter-facet}
  \uses{1-2-5-facet}
  % \lean{}
  % \leanok

  Every proper face $\tau \prec \sigma$ of a polyhedral cone $\sigma$ is the intersection of the facets of $\sigma$ containing $\tau$.
\end{proposition}

n25606.content:
\begin{definition}[Dual face]
  \label{1-2-10-dual-face}
  \uses{1-2-3-dual-cone, 1-2-5-face}
  % \lean{}
  % \leanok

  Given a cone $\sigma$ and a face $\tau \preceq \sigma$, the {\bf dual face} to $\tau$ is
  $$\tau^* := \sigma^\vee \cap \tau^\perp$$
\end{definition}

n25607.content:
\begin{proposition}[The dual face is a face of the dual]
  \label{1-2-10-dual-face-face-dual}
  \uses{1-2-10-dual-face}
  % \lean{}
  % \leanok

  If $\tau \preceq \sigma$, then $\tau^* \preceq \sigma^\vee$.
\end{proposition}

n25609.content:
\begin{proposition}[The double dual of a face]
  \label{1-2-10-double-dual-face-dual-face}
  \uses{1-2-10-dual-face}
  % \lean{}
  % \leanok

  If $\tau \preceq \sigma$, then $\tau^{**} = \tau$.
\end{proposition}

n25611.content:
\begin{proposition}[The dual of a face is antitone]
  \label{1-2-10-dual-face-antitone}
  \uses{1-2-10-dual-face}
  % \lean{}
  % \leanok

  If $\tau' \preceq \tau \preceq \sigma$, then $\tau' \preceq \tau$.
\end{proposition}

n25613.content:
\begin{proposition}[The dimension of the dual of a face]
  \label{1-2-10-dim-dual-face}
  \uses{1-2-10-dual-face}
  % \lean{}
  % \leanok

  If $\tau \preceq \sigma$, then
  $$\dim \tau + \dim \tau^* = \dim N.$$
\end{proposition}

n25615.content:
\begin{definition}[Relative interior]
  \label{1-2-rel-interior}
  % \uses{}
  \lean{intrinsicInterior}
  \leanok

  The {\bf relative interior}, aka {\bf intrinsic interior}, of a cone $\sigma$ is the interior of $\sigma$ as a subset of its span.
\end{definition}

n25616.content:
\begin{lemma}[The relative interior in terms of the inner product]
  \label{1-2-rel-interior-inner}
  \uses{1-2-rel-interior}
  % \lean{}
  % \leanok

  For a cone $\sigma$,
  $$u \in \Relint(\sigma) \iff \forall m \in \sigma^\vee \setminus \sigma^\perp, \langle m, u\rangle > 0$$
\end{lemma}

n25618.content:
\begin{lemma}[Relative interior of a dual face]
  \label{1-2-rel-interior-dual-face}
  \uses{1-2-10-dual-face, 1-2-rel-interior}
  % \lean{}
  % \leanok

  If $\tau \preceq \sigma$ and $m \in \sigma^\vee$, then
  $$m \in \Relint(\tau^*) \iff \tau = H_m \cap \sigma$$
\end{lemma}

n25620.content:
\begin{lemma}[Minimal face of a cone]
  \label{1-2-min-face}
  \uses{1-2-5-face, 1-2-rel-interior}
  % \lean{}
  % \leanok

  If $\sigma$ is a cone, then $W := \sigma \cap (-\sigma)$ is a subspace. Furthermore,
  $W = H_m \cap \sigma$ whenever $m \in \Relint(\sigma^\vee)$.
\end{lemma}

n25622.content:
\begin{definition}[Salient cones]
  \label{1-2-12-salient-cone}
  % \uses{}
  \lean{ConvexCone.Salient}
  \leanok

  A cone $\sigma$ is {\bf salient}, aka {\bf pointed} or {\bf strongly convex}, if $\sigma \cap (-\sigma) = \{0\}$.
\end{definition}

n25623.content:
\begin{proposition}[Alternative definitions of salient cones]
  \label{1-2-12-salient-cone-tfae}
  \uses{1-2-3-dual-cone, 1-2-12-salient-cone}
  % \lean{}
  % \leanok

  The following are equivalent
  \begin{enumerate}
    \item $\sigma$ is salient
    \item $\{0\} \preceq \sigma$
    \item $\sigma$ contains no positive dimensional subspace
    \item $\dim \sigma^\vee = \dim N$
  \end{enumerate}
\end{proposition}

n25625.content:
\begin{lemma}[Separation lemma]
  \label{1-2-13-separation-lemma}
  \uses{1-2-1-polyhedral-cone, 1-2-5-face}
  % \lean{}
  % \leanok

  Let $\sigma_1, \sigma_2$ be polyhedral cones meeting along a common face $\tau$. Then
  $$\tau = H_m \cap \sigma_1 = H_m \cap \sigma_2$$
  for any $m \in \Relint(\sigma_1^\vee \cap (-\sigma_2)^\vee)$.
\end{lemma}

n25627.content:
\begin{definition}[Rational cone]
  \label{1-2-14-rat-cone}
  \uses{1-2-1-cone-hull}
  % \lean{}
  % \leanok

  A cone $\sigma \subseteq N_\R$ is {\bf rational} if $\sigma = \Cone(S)$ for some finite set $S \subseteq N$.
\end{definition}

n25628.content:
\begin{lemma}[Faces of a rational cone]
  \label{1-2-14-face-rat-cone}
  \uses{1-2-5-face, 1-2-14-rat-cone}
  % \lean{}
  % \leanok

  If $\tau \preceq \sigma$ is a face of a rational cone, then $\tau$ itself is rational.
\end{lemma}

n25630.content:
\begin{lemma}[The dual of a rational cone]
  \label{1-2-14-dual-rat-cone}
  \uses{1-2-3-dual-cone, 1-2-14-rat-cone}
  % \lean{}
  % \leanok

  $\sigma^\vee$ is a rational cone iff $\sigma$ is.
\end{lemma}

n25632.content:
\begin{definition}[Ray generator]
  \label{1-2-ray-gen}
  \uses{1-2-5-edge, 1-2-14-rat-cone}
  % \lean{}
  % \leanok

  If $\rho$ is an edge of a rational cone $\sigma$, then the monoid $\rho \cap N$ is generated by a unique element $u_\rho \in \rho \cap N$, which we call the {\bf ray generator} of $\rho$.
\end{definition}

n25633.content:
\begin{definition}[Minimal generators]
  \label{1-2-min-gen}
  \uses{1-2-ray-gen}
  % \lean{}
  % \leanok

  The {\bf minimal generators} of a rational cone $\sigma$ are the ray generators of its edges.
\end{definition}

n25634.content:
\begin{lemma}[A rational cone is generated by its minimal generators]
  \label{1-2-15-cone-hull-min-gen}
  \uses{1-2-12-salient-cone, 1-2-min-gen}
  % \lean{}
  % \leanok

  A salient convex rational polyhedral cone is generated by its minimal generators.
\end{lemma}

n25636.content:
\begin{definition}[Regular cone]
  \label{1-2-16-reg-cone}
  \uses{1-2-min-gen}
  % \lean{}
  % \leanok

  A salient rational polyhedral cone $\sigma$ is {\bf regular}, aka {\bf smooth}, if its minimal generators form part of a $\Z$-basis of $N$.
\end{definition}

n25637.content:
\begin{definition}[Simplicial cone]
  \label{1-2-16-simplicial-cone}
  \uses{1-2-min-gen}
  % \lean{}
  % \leanok

  A salient rational polyhedral cone $\sigma$ is {\bf simplicial} if its minimal generators are $\R$-linearly independent.
\end{definition}

n25638.content:
\begin{definition}[Dual lattice of a cone]
  \label{1-2-17-dual-lat-cone}
  \uses{1-2-3-dual-cone}
  % \lean{}
  % \leanok

  If $\sigma \subseteq N_\R$ is a polyhedral cone, then the lattice points
  \[
    S_\sigma := \sigma^\vee \cap M
  \]
  form a monoid.
\end{definition}

n25639.content:
\begin{proposition}[Gordan's lemma]
  \label{1-2-17-gordan-lemma}
  \uses{1-2-17-dual-lat-cone}
  % \lean{}
  % \leanok

  $S_\sigma$ is finitely generated as a monoid.
\end{proposition}

n25641.content:
\begin{definition}[Affine toric variety of a rational polyhedral cone]
  \label{1-2-18-aff-tor-var-rat-polyhedral-cone}
  \uses{5-1-tor-var, 1-2-17-dual-lat-cone}
  % \lean{}
  % \leanok

  $U_\sigma := \Spec \bbC[S_\sigma]$ is an affine toric variety.
\end{definition}

n25642.content:
\begin{theorem}[Dimension of the affine toric variety of a rational polyhedral cone]
  \label{1-2-18-dim-aff-tor-var-rat-polyhedral-cone}
  \uses{1-2-12-salient-cone, 1-2-18-aff-tor-var-rat-polyhedral-cone}
  % \lean{}
  % \leanok

  \[
    \dim U_\sigma = \dim N \iff \text{ the torus of $U_\sigma$ is } T_N = N \otimes_[\Z] \bbC^* \iff \sigma \text{ is salient}.
  \]
\end{theorem}

n25644.content:
\begin{proposition}[The irreducible elements of the dual lattice of a cone]
  \label{1-2-22-irred-dual-lat}
  \uses{0-irred, 1-2-min-gen, 1-2-12-salient-cone, 1-2-17-dual-lat-cone}
  % \lean{}
  % \leanok

  If $\sigma \subseteq N_\R$ is salient of maximal dimension, then the irreducible elements of $S_\sigma$ are precisely the minimal generators of $\sigma^\vee$.
\end{proposition}

n25646.content:
\begin{definition}[Spec as a functor on algebras]
  \label{0-spec-alg}
  % \uses{}
  \lean{AlgebraicGeometry.algSpec}
  \leanok

  Spec is a contravariant functor from the category of $R$-algebras
  to the category of schemes over $\Spec_R$.
\end{definition}

n25647.content:
\begin{proposition}[Spec as a functor on algebras is fully faithful]
  \label{0-full-faithful-spec-alg}
  \uses{0-spec-alg}
  \lean{AlgebraicGeometry.preservesLimitsOfSize_algSpec, AlgebraicGeometry.algSpec.instFull, AlgebraicGeometry.algSpec.instFaithful, AlgebraicGeometry.algSpec.fullyFaithful}
  \leanok

  Spec is a fully faithful contravariant functor from the category of $R$-algebras
  to the category of schemes over $\Spec_R$, preserving all limits.
\end{proposition}

n25648.content:
\begin{proof}
  \uses{0-slice-adj, 0-over-lim}
  \leanok

  $\Spec : \Ring \to \Sch$ is a fully faithful contravariant functor which preserves all limits,
  hence so is $\Spec : \Ring_R \to \Sch_{\Spec R}$ by Proposition \ref{0-over-lim}
  (alternatively, by Proposition \ref{0-slice-adj}).
\end{proof}

n25649.content:
\begin{definition}[Spec as a functor on bialgebras]
  \label{0-spec-bialg}
  \uses{0-full-faithful-spec-alg}
  \lean{AlgebraicGeometry.bialgSpec}
  \leanok

  Spec is a contravariant functor from the category of $R$-bialgebras
  to the category of monoid schemes over $\Spec_R$.
\end{definition}

n25650.content:
\begin{proposition}[Spec as a functor on bialgebras is fully faithful]
  \label{0-full-faithful-spec-bialg}
  \uses{0-spec-bialg}
  \lean{AlgebraicGeometry.bialgSpec.instFull, AlgebraicGeometry.bialgSpec.instFaithful, AlgebraicGeometry.bialgSpec.fullyFaithful}
  \leanok

  Spec is a fully faithful contravariant functor from the category of $R$-bialgebras
  to the category of monoid schemes over $\Spec_R$.
\end{proposition}

n25651.content:
\begin{proof}
  \uses{0-full-faithful-grp, 0-full-faithful-spec-alg}
  \leanok

  $\Spec : \Ring_R \to \Sch_{\Spec R}$ is a fully faithful contravariant functor
  preserving all limits according to Proposition \ref{0-spec-alg},
  therefore $\Spec : \Bialg_R \to \MonSch_{\Spec R}$ too is fully faithful
  according to \ref{0-full-faithful-grp}.
\end{proof}

n25652.content:
\begin{proposition}[Spec sends cocommutative bialgebras to commutative monoid schemes]
  \label{0-spec-cocomm-bialg}
  \uses{0-spec-hopf}
  \lean{AlgebraicGeometry.isCommMonObj_spec_asOver_spec, AlgebraicGeometry.instCommGrpObjSpecAsOverSpec}
  \leanok

  If $A$ is a cocommutative bialgebra over $R$, then $\Spec A$ is a commutative monoid scheme.
\end{proposition}

n25653.content:
\begin{proof}
  % \uses{}
  \leanok

  Diagrams are the same up to identifying $\Spec (A \otimes A)$ with $\Spec A \otimes \Spec A$.
\end{proof}

n25654.content:
\begin{definition}[Spec as a functor on Hopf algebras]
  \label{0-spec-hopf}
  \uses{0-full-faithful-spec-alg}
  \lean{AlgebraicGeometry.hopfSpec}
  \leanok

  Spec is a contravariant functor from the category of $R$-Hopf algebras to the category of group schemes over $\Spec_R$.
\end{definition}

n25655.content:
\begin{proposition}[Spec as a functor on Hopf algebras is fully faithful]
  \label{0-full-faithful-spec-hopf}
  \uses{0-spec-hopf}
  \lean{AlgebraicGeometry.hopfSpec.instFull, AlgebraicGeometry.hopfSpec.instFaithful, AlgebraicGeometry.hopfSpec.fullyFaithful}
  \leanok

  Spec is a fully faithful contravariant functor from the category of $R$-Hopf algebras to the category of group schemes over $\Spec_R$.
\end{proposition}

n25656.content:
\begin{proof}
  \uses{0-full-faithful-grp, 0-full-faithful-spec-alg}
  \leanok

  $\Spec : \Ring_R \to \Sch_{\Spec R}$ is a fully faithful contravariant functor
  preserving all limits according to Proposition \ref{0-spec-alg},
  therefore $\Spec : \Hopf_R \to \GrpSch_{\Spec R}$ too is fully faithful
  according to \ref{0-full-faithful-grp}.
\end{proof}

n25657.content:
\begin{proposition}[Essential image of Spec on algebras]
  \label{0-ess-image-spec-alg}
  \uses{0-spec-alg}
  \lean{AlgebraicGeometry.essImage_algSpec}
  \leanok

  The essential image of $\Spec : \Ring_R \to \Sch_{\Spec R}$ is precisely
  affine schemes over $\Spec R$.
\end{proposition}

n25659.content:
\begin{proposition}[Essential image of Spec on bialgebras]
  \label{0-ess-image-spec-bialg}
  \uses{0-spec-bialg}
  \lean{AlgebraicGeometry.essImage_bialgSpec}
  \leanok

  The essential image of $\Spec : \Bialg_R \to \GrpSch_{\Spec R}$ is precisely
  affine monoid schemes over $\Spec R$.
\end{proposition}

n25661.content:
\begin{proposition}[Essential image of Spec on Hopf algebras]
  \label{0-ess-image-spec-hopf}
  \uses{0-spec-hopf}
  \lean{AlgebraicGeometry.essImage_hopfSpec}
  \leanok

  The essential image of $\Spec : \Hopf_R \to \GrpSch_{\Spec R}$ is precisely affine group schemes over $\Spec R$.
\end{proposition}

n25663.content:
\begin{definition}[The diagonalisable group scheme functor]
  \label{0-diag}
  \uses{0-grp-alg, 0-hopf-alg-equiv-cogrp-alg, 0-spec-hopf}
  \lean{AlgebraicGeometry.Scheme.Diag}
  \leanok

  Let $G$ be a commutative group and $S$ a base scheme.
  The diagonalisable group scheme $D_S(G)$ is defined as the base-change of $\Spec \Z[G]$ to $S$.
  For a commutative ring $R$, we write $D_R(G) := D_{\Spec R}(G)$.
\end{definition}

n25664.content:
\begin{definition}[Diagonalisable group schemes]
  \label{0-is-diag}
  \uses{0-diag}
  \lean{AlgebraicGeometry.Scheme.IsDiagonalisable}
  \leanok

  An algebraic group $G$ over $\Spec R$ is {\bf diagonalisable} if it is isomorphic to $D_R(G)$ for some commutative group $G$.
\end{definition}

n25665.content:
\begin{lemma}[The diagonalisable group scheme torus over $\Spec R$]
  \label{0-diag-spec}
  \uses{0-torus}
  \lean{AlgebraicGeometry.Scheme.diagSpecIso, AlgebraicGeometry.Scheme.splitTorusIso}
  \leanok

  Let $R$ be a commutative ring and $M$ an abelian monoid.
  Then $D_R(M)$ is isomorphic to $\Spec R[M]$.
\end{lemma}

n25666.content:
\begin{proof}
  % \uses{}
  \leanok

  Ask any toddler on the street.
\end{proof}

n25667.content:
\begin{theorem}
  \label{0-diag-iff-grp-like-span}
  \uses{0-diag, 0-is-diag}
  \lean{AlgebraicGeometry.Scheme.isDiagonalisable_iff_span_isGroupLikeElem_eq_top}
  \leanok

  An algebraic group $G$ over a field $k$ is diagonalizable if and only if $\Gamma(G)$ is spanned by its group-like elements.
\end{theorem}

n25669.content:
\begin{theorem}
  \label{0-full-faithful-diag}
  \uses{0-diag}
  \lean{AlgebraicGeometry.Scheme.full_diagFunctor, AlgebraicGeometry.Scheme.faithful_diagFunctor}
  \leanok

  Let $R$ be a domain.
  The functor $D_R(G) := G \rightsquigarrow \Spec R[G]$ from the category of groups to the category of group schemes over $\Spec R$ is fully faithful.
\end{theorem}

n25670.content:
\begin{proof}
  \uses{0-full-faithful-spec-hopf, 0-full-faithful-grp-alg}
  \leanok

  Compose Propositions \ref{0-full-faithful-spec-hopf} and \ref{0-full-faithful-grp-alg}.

  Also see Theorem 12.9(a) in \cite{Milne_2017}. See SGA III Exposé VIII for a proof that works for $R$ an arbitrary commutative ring.
\end{proof}

n25671.content:
\begin{proposition}[Morphisms between diagonalisable group schemes are affine]
  \label{0-diag-aff-hom}
  \uses{0-diag}
  % \lean{}
  % \leanok

  Let $S$ be a scheme.
  Let $M, N$ be commutative monoids and $f : M \to N$ a monoid hom.
  Then the map $D_S(f) : D_S(N) \to D_S(M)$ is affine.
\end{proposition}

n25672.content:
\begin{proof}
  % \uses{}
  % \leanok

  $\Spec f : \Spec \Z[N] \to \Spec \Z[M]$ is affine, since it's a morphism of affine schemes.
  Therefore $D_S(f)$ is affine, as affine morphisms are preserved under base change.
\end{proof}

n25673.content:
\begin{proposition}[Closed embeddings between diagonalisable group schemes]
  \label{0-diag-closed-emb}
  \uses{0-diag}
  % \lean{}
  % \leanok

  Let $S$ be a scheme.
  Let $M, N$ be commutative monoids and $f : M \to N$ a surjective monoid hom.
  Then the map $D_S(f) : D_S(N) \to D_S(M)$ is a closed embedding.
\end{proposition}

n25674.content:
\begin{proof}
  % \uses{}
  % \leanok

  Since $f$ is surjective, the corresponding map $\hat f : \Z[M] \to \Z[N]$ is surjective too.
  Hence $\Spec \hat f : \Spec \Z[N] \to \Spec \Z[M]$ is a closed embedding.
  Therefore $D_S(f)$ is a closed embedding, as closed embeddings are preserved under base change.
\end{proof}

n25675.content:
\begin{proposition}[Faithfully flat morphisms between diagonalisable group schemes]
  \label{0-diag-faithful-flat}
  \uses{0-diag}
  % \lean{}
  % \leanok

  Let $S$ be a scheme.
  Let $G, H$ be abelian groups and $f : G \to H$ an injective group hom.
  Then the map $D_S(f) : D_S(H) \to D_S(G)$ is faithfully flat.
\end{proposition}

n25676.content:
\begin{proof}
  \uses{0-grp-alg-free}
  % \leanok

  Since $f$ is injective, $\Z[H]$ is a free module over $\Z[G]$ by Proposition \ref{0-grp-alg-free},
  hence the map $\Z[G] \to \Z[H]$ is faithfully flat and so is $\Spec \Z[H] \to \Spec \Z[G]$.
  Therefore $D_S(f)$ is faithfully flat,
  as faithfully flat morphisms are preserved under base change.
\end{proof}

n25677.content:
\begin{proposition}[A subgroup of a diagonalisable group scheme is a diagonalisable group scheme]
  \label{0-subgroup-diag}
  \uses{0-diag}
  % \lean{}
  % \leanok

  Let $R$ be a domain. Let $G$ be an abelian group.
  If $H$ is a closed subgroup of $D_R(G)$, then $H$ is a diagonalisable group scheme.
\end{proposition}

n25679.content:
\begin{proposition}[Diagonalisable group scheme of a torsion group is disconnected]
  \label{0-diag-tors}
  \uses{0-diag}
  % \lean{}
  % \leanok

  Let $G$ be an abelian group with an element of torsion $n$.
  Let $R$ be a commutative ring with $n$ invertible.
  Then $D_R(G)$ is disconnected.
\end{proposition}

n25680.content:
\begin{proof}
  \uses{0-diag-spec}
  % \leanok

  Say $x \in G$ is such that $x^n = 1$. Then
  \[e : R[G] := \frac 1n \sum_{i = 0}^n x^i\]
  is such that $e ^ 2 = e$.
  We are done by Proposition \ref{0-diag-spec}.
\end{proof}

n25681.content:
\begin{definition}[The split torus]
  \label{0-torus}
  \lean{AlgebraicGeometry.Scheme.SplitTorus, AlgebraicGeometry.Scheme.Diag.canonicallyOver}
  \leanok

  The split torus $\G_m^n$ over a scheme $S$ is the pullback of
  $\Spec \Z[x_1^{\pm 1}, \dotsc, x_n^{\pm 1}]$ along the unique map $S \to \Spec \Z$.
\end{definition}

n25682.content:
\begin{lemma}[Diag is a group isomorphism on hom sets]
