n25699.content:
\begin{proposition}[A subgroup of a torus is a torus]
  \label{1-1-1-subgroup-torus}
  \uses{0-torus}
  % \lean{}
  % \leanok

  Let $R$ be a commutative ring of characteristic zero.
  Let $T$ be a split torus.
  If $H \subseteq T$ is a connected closed subgroup, then $H$ is a split torus.
\end{proposition}

n25701.content:
\begin{definition}[Toric varieties]
  \label{5-1-tor-var}
  \uses{0-torus}
  \lean{AlgebraicGeometry.ToricVariety}
  \leanok

  Let $k$ be a field.
  Let $T$ be a torus over $k$.
  A \emph{toric variety} structure on a scheme $X$ over $k$ consists the following data:
  \begin{itemize}
    \item a torus $T$ over $k$,
    \item a group action $T \times X \to X$ over $k$.
    \item a dominant open immersion $i : T \hookrightarrow X$ over $k$ that is $T$-equivariant.
  \end{itemize}
\end{definition}

n25703.content:
\begin{proposition}[The diagonalisable group scheme of an affine monoid algebra is an affine toric variety]
  \label{1-1-aff-tor-var-diag-aff-mon}
  \uses{0-diag, 5-1-tor-var}
  % \lean{}
  % \leanok

  Let $k$ be a field.
  Let $G$ be a finitely generated free abelian group.
  Let $M$ be an affine monoid with Grothendieck group $G$.
  Then $D_k(M)$ is an affine toric variety over $k$ with torus $D_k(G)$.
\end{proposition}

n25705.content:
\begin{definition}[The character eigenspace]
  \label{1-1-char-eigenspace}
  \uses{0-char}
  % \lean{}
  % \leanok

  For a finite dimensional representation of a torus $T$ on $W$, the {\bf character eigenspace} of a character $\chi \in X(T)$ is
  \[
    W_m = \{w\in W : t\cdot w = \chi(t)\text{ for all } t\in T \}.
  \]
\end{definition}

n25706.content:
\begin{proposition}[Decomposition into character eigenspaces]
  \label{1-1-2-char-eigenspace-direct-sum}
  \uses{1-1-char-eigenspace}

  The space decomposes into the direct sum of the character eigenspaces.
\end{proposition}

n25708.content:
\begin{definition}
  \label{1-1-tor-act-alg}
  \uses{0-torus}
  % \lean{}
  % \leanok

  There is a torus action on the semigroup algebra $\bbC[M]$: given $t\in T_N$ and $f\in \bbC[M]$ define
  \[
    t \cdot f = (p \mapsto f(t^{-1}p)).
  \]
\end{definition}

n25709.content:
\begin{lemma}
  \label{1-1-16-total-red}
  \uses{1-1-tor-act-alg}
    Let $A \subseteq \bbC[M]$ be a stable subspace, then
    \[
      A = \bigoplus_{\chi^m \in A} \bbC \cdot \chi^m.
    \]
\end{lemma}

n25711.content:
\begin{definition}[Characters of a toric variety]
  \label{5-2-char-tor-var}
  % \uses{}
  % \lean{}
  % \leanok

  Let $k$ be a field.
  Let $T$ be a torus over $k$.
  Let $V$ be a toric variety with torus $k$.
  The \emph{characters} $X(V)$ of $V$ are defined as the intersection of $X(T)$
  with the image of the map $k[V] \to k[T]$ of coordinate rings
  induced by the embedding $T \hookrightarrow V$.
\end{definition}

n25712.content:
\begin{proposition}[Characters of a toric variety are an affine monoid]
  \label{5-2-char-tor-var-aff-mon}
  \uses{5-2-char-tor-var}
  % \lean{}
  % \leanok

  Let $k$ be a field.
  Let $T$ be a torus over $k$.
  Let $V$ be a toric variety with torus $k$.
  Then $X(V)$ is an affine monoid.
\end{proposition}

n25714.content:
\begin{definition}[Lattice ideal]
  \label{1-1-10-lat-ideal}
  % \uses{}
  \lean{AddMonoidAlgebra.monoidIdeal}
  \leanok

  Let $R$ be a ring.
  Let $G$ be a free abelian group and $M$ an affine monoid whose Grothendieck group is $G$.
  Let $L \le G$ be a sublattice.
  The \emph{lattice ideal} of $L$ is the $R$-ideal of $R[M]$ defined by
  \[
    I_L := \langle X^\alpha - X^\beta | \alpha, \beta \in M, \alpha - \beta \in L\rangle.
  \]
\end{definition}

n25715.content:
\begin{definition}
  \label{1-1-10-tor-ideal}
  \uses{1-1-10-lat-ideal}
  \lean{AddMonoidAlgebra.IsToricIdeal}
  \leanok

  Let $R$ be a ring. Let $M$ be an affine monoid.
  A \emph{toric ideal} is a prime lattice $R$-ideal of $R[M]$.
\end{definition}

n25716.content:
\begin{proposition}[An ideal is toric iff it is prime and generated by binomials]
  \label{1-1-11-toric-ideal-gen-binomial}
  \uses{1-1-10-tor-ideal}
  \lean{AddMonoidAlgebra.isToricIdeal_iff_exists_span_single_sub_single}
  % \leanok

  An ideal is toric if and only if it's prime and generated by binomials $X^\alpha - X^\beta$.
\end{proposition}

n25718.content:
\begin{proposition}[The vanishing ideal of a closed toric embedding]
  \label{5-3-van-tor-emb}
  \uses{1-1-phiAprime, 1-1-7-ya, 1-1-10-lat-ideal}
  % \lean{}
  % \leanok

  Let $k$ be a field.
  Let $V$ be a toric variety over $k$.
  Let $i : V \hookrightarrow \mathbb{A}^n$ be a closed toric embedding.
  Then the vanishing ideal of $i$ is toric.
\end{proposition}

n25720.content:
\begin{definition}
  \label{1-1-phiAprime}
  \uses{0-char}
  % \lean{}
  % \leanok

  Let $S$ be a scheme. Let $G$ be an abelian group.
  Let $s$ be an arbitrary indexing type, and $\MCA : s \to G$ an indexed family.
  Let $f'_\MCA$ be the map
  \begin{align*}
    \Z^{\oplus s} & \to G \\
    e_i & \mapsto \MCA_i.
  \end{align*}
  and define $\Phi'_\MCA : D_S(G) \to \G_m^s$ as the image under $D_S$ of $f'_\MCA$.
\end{definition}

n25721.content:
\begin{definition}
  \label{1-1-phiA}
  \uses{1-1-phiAprime}
  % \lean{}
  % \leanok

  Let $S$ be a scheme. Let $G$ be an abelian group.
  Let $s$ be an arbitrary indexing type, and $\MCA : s \to G$ an indexed family.
  Let $f_\MCA$ be the map
  \begin{align*}
    \N^{\oplus s} & \to G \\
    e_i & \mapsto \MCA_i.
  \end{align*}
  and define $\Phi_\MCA : D_S(G) \to \mathbb A^s$ as the image under $D_S$ of $f_\MCA$.
\end{definition}

n25722.content:
\begin{definition}
  \label{1-1-7-ya}
  \uses{1-1-phiA}
  % \lean{}
  % \leanok

  $Y_\MCA$ is the scheme theoretic closure of $\im \Phi_\MCA$ in $\mathbb A^s$.
\end{definition}

n25723.content:
\begin{proposition}
  \label{1-1-8-aff-tor-var-ya}
  \uses{1-1-7-ya}
  % \lean{}
  % \leanok

  Let the base be $S=\Spec k$ for a field $k$, then $Y_\MCA$ is a toric variety.
\end{proposition}

n25724.content:
\begin{proof}
  \uses{1-1-1-group-hom-torus}
  % \leanok

  {\textbf Torus: }
  Define the torus $T'$ to be the one we get from \ref{1-1-1-group-hom-torus} with quotient map $\pi:T \to T'$.
  {\textbf Open embedding: }
  Since both $Y_{\MCA},T'$ are closures of $\Phi,\Phi'$ and $\G_m^n\to\mathbb{A}^n$ is an open embedding
  we get an open embedding $\iota:T' \to Y_{\MCA}$ such that the map $\phi:T \to Y_{\MCA}$ factors as
  $\phi = \iota \circ \pi$.
  {\textbf Dominant: } Since $\phi$ is dominant, so is $\iota$.
  {\textbf Action: }
  Since $\G_m^n$ acts on $\mathbb{A}^n$, we get a morphism $a':T' \times_S Y_\MCA \to \mathbb{A}^n$.
  As $T'\times_S Y_\MCA$ is reduced (TODO add lemma), to show that this factors through $Y_\MCA$ it suffices to check
  that the image lies in $Y_\MCA$.

  First, $T'\times_S T' \to T'\times Y_\MCA$ is dominant, since $T'$ is flat and flat base change preserves dominance (TODO add lemma).
  Since the image of $T'\times_S T'$ is $T'$ we're done for topological reasons.

  {\textbf Equivariant: } The inclusion of the torus is equivariant, since $\G_m^n \to \mathbb{A}^n$ is.
\end{proof}

n25725.content:
\begin{proposition}
  \label{1-1-8-char-ya}
  \uses{1-1-7-ya}
  % \lean{}
  % \leanok

  The character lattice of the torus of $Y_\MCA$ is $\Z \MCA$.
\end{proposition}

n25726.content:
\begin{proof}
  \uses{0-char-torus}
  % \leanok

  $\Phi_\MCA: T_N \to \G_m^s$ factors through the torus of $Y_\MCA$.
  The conclusion follows from looking at the corresponding maps of character lattices.
\end{proof}

n25727.content:
\begin{proposition}
  \label{1-1-9-ideal-ya}
  \uses{1-1-phiAprime, 1-1-7-ya, 1-1-10-lat-ideal}
  % \lean{}
  % \leanok

  Let $R$ be a commutative ring. Let $G$ be an abelian group.
  Let $s$ be an arbitrary indexing type, and $\MCA : s \to G$ an indexed family.
  Let $L$ be the kernel of $f'_\MCA : \Z^{\oplus s} \to G$.
  Then the ideal of the affine toric variety $Y_\MCA$ is
  \[
    I(Y_\MCA) = I_L.
  \]
\end{proposition}

n25728.content:
\begin{proof}
  \uses{0-diag-spec}
  % \leanok

  By the definition of $Y_\MCA$ as the scheme-theoretic closure of $\Phi_\MCA$,
  we have $I(Y_\MCA) = \ker R[f_\MCA] = \ker R[f'_\MCA]$ where, recall,
  $f_\MCA : \N^s \to G, f'_\MCA : \Z^s \to G$ are both given by $e_i \mapsto \MCA_i$,
  and $R[f_\MCA] : R[\N^s] \to R[G]$ is the pushforward.

  By Proposition \ref{0-ker-mon-alg} with $G := \Z, S := {1}$,
  \[
    \ker R[f_\MCA] = \Span\{X^\alpha - X^\beta | \alpha, \beta \in \N^s, f(\alpha) = f(\beta)\}
      = \Span\{X^\alpha - X^\beta | \alpha, \beta \in \N^s, \alpha - \beta \in L\}.
  \]
\end{proof}

n25729.content:
\begin{proposition}
  \label{1-1-14-spec-aff-mon-alg}
  \uses{0-aff-mon, 1-1-7-ya}
  % \lean{}
  % \leanok

  If $S$ is an affine monoid and $\mathcal A$ is a finite set generating $S$ as a monoid, then $\Spec \Bbbk[S] = Y_{\mathcal A}$.
\end{proposition}

n25730.content:
\begin{proof}
  \uses{1-1-8-aff-tor-var-ya}
  % \leanok

  We get a $\Bbbk$-algebra homomorphism $\pi : \Bbbk[x_1, \dotsc, x_s] \to \Bbbk[\Z S]$ given by $\mathcal A$; this induces a morphism $\Phi_{\mathcal A} : T \to \Bbbk^s$. The kernel of $\pi$ is the toric ideal of $Y_{\mathcal A}$ and $\pi$ is clearly surjective, so $Y_{\mathcal A} = \mathbb V(\ker(\pi)) = \Spec \Bbbk[x_1, \dotsc, x_s] / \ker(\pi) = \Spec \bbC[S]$.
\end{proof}

n25731.content:
\begin{proposition}
  \label{1-1-10-tor-ideal-ya}
  \uses{1-1-7-ya, 1-1-9-ideal-ya}
  % \lean{}
  % \leanok

  The ideal of $Y_\MCA$ is a toric ideal.
\end{proposition}

n25733.content:
\begin{theorem}[Affine toric varieties come from affine monoids]
  \label{5-1-aff-tor-var-iso-diag-aff-mon}
  \uses{0-aff-mon, 5-1-tor-var, 5-1-tor-hom, 1-1-7-ya, 1-1-10-lat-ideal}
  % \lean{}
  % \leanok

  Let $k$ be a field.
  Let $T$ be a torus over $k$.
  Let $V$ be a toric variety with torus $k$.
  Then there exists a torus isomorphism $V \cong D_k(X(V))$.
\end{theorem}
